insert into sources (id, mission, instrument, product_id, url, attribution, license_note) values ('src-34baed2a49a1', 'Mars 2020 (Perseverance)', 'SuperCam, PIXL, Mastcam-Z', null, 'https://www.jpl.nasa.gov/news/nasa-discovery-reveals-complex-water-systems-on-early-mars/', 'NASA/JPL-Caltech; Bedford et al. (2026), Communications Earth & Environment', null) on conflict (id) do update set mission = excluded.mission, instrument = excluded.instrument, product_id = excluded.product_id, url = excluded.url, attribution = excluded.attribution, license_note = excluded.license_note;
