insert into sources (id, mission, instrument, product_id, url, attribution, license_note) values ('src-e419d55837ab', 'Mars Reconnaissance Orbiter', 'HiRISE', 'JEZ_hirise_soc_006_DTM_MOLAtopography_DeltaGeoid_1m_Eqc_latTs0_lon0_blend40', 'https://astrogeology.usgs.gov/search/map/mars_2020_terrain_relative_navigation_hirise_dtm_mosaic', 'NASA/JPL-Caltech/University of Arizona; USGS Astrogeology — Fergason et al. (2020), doi:10.5066/P9REJ9JN', 'USGS: «Please cite authors»') on conflict (id) do update set mission = excluded.mission, instrument = excluded.instrument, product_id = excluded.product_id, url = excluded.url, attribution = excluded.attribution, license_note = excluded.license_note;
insert into regions (id, display_order, status, is_example, dataset_version, name, summary, center_lat_deg, center_lon_east_deg, center_approximate, thumbnail_url, frame_id, frame_description, source_crs, min_x, min_y, max_x, max_y, elevation_min_m, elevation_max_m, mission_objective, route_defaults, available_layers, available_pois, available_routes, available_terrain_3d) values ('jezero-margin', 0, 'active', false, 'hirise-v1', '{"es":"Cráter Jezero — Margin Unit","en":"Jezero Crater — Margin Unit"}'::jsonb, '{"es":"La antigua orilla de un lago donde Perseverance halló rastros de tres sistemas de agua distintos.","en":"The ancient shoreline of a lake where Perseverance found traces of three distinct water systems."}'::jsonb, 18.487, 77.325, false, null, 'jezero-margin-local-m', '{"es":"Metros sobre el terreno desde la esquina suroeste de un recorte de 4 × 3 km centrado en 18.487° N, 77.325° E: x al este, y al norte, z elevación sobre el geoide de Marte.","en":"Ground metres from the south-west corner of a 4 × 3 km crop centred at 18.487° N, 77.325° E: x east, y north, z elevation above the Mars geoid."}'::jsonb, 'Mars 2000 esfera IAU (R = 3 396 190 m), equirectangular; transformación en pipeline/jezero/procesar_dtm.py', 0.0, 0.0, 4000.0, 3000.0, -2443.1, -1995.0, '{"es":"Salir de la base y visitar, en orden, las rocas con carbonato donde Perseverance tomó muestras en la Margin Unit; la parada opcional es Eremita Mesa, al pie del borde del cráter.","en":"Leave the base and visit, in order, the carbonate-bearing rocks Perseverance sampled in the Margin Unit; the optional stop is Eremita Mesa, at the foot of the crater rim."}'::jsonb, '{"max_slope_deg":20.0,"eva_time_limit_min":360.0,"profiles":["shortest","fastest","safest"],"include_return":true,"soft_soil_penalty":2.0,"walking_model":"tobler-eva-v1"}'::jsonb, true, true, true, true);
insert into region_facts (region_id, ord, text, certainty) values ('jezero-margin', 0, '{"es":"La Margin Unit es roca ígnea rica en olivino, no sedimento del lago como se creía desde órbita.","en":"The Margin Unit is olivine-rich igneous rock, not lake sediment as orbital data suggested."}'::jsonb, 'confirmed');
insert into region_fact_sources (region_id, fact_ord, ord, source_id) values ('jezero-margin', 0, 0, 'src-34baed2a49a1');
insert into region_facts (region_id, ord, text, certainty) values ('jezero-margin', 1, '{"es":"Episodio 1: agua subterránea con CO₂ formó crestas de carbonato en las fracturas de las zonas bajas.","en":"Episode 1: CO₂-rich groundwater formed carbonate ridges in fractures at lower elevations."}'::jsonb, 'interpretation');
insert into region_fact_sources (region_id, fact_ord, ord, source_id) values ('jezero-margin', 1, 0, 'src-34baed2a49a1');
insert into region_facts (region_id, ord, text, certainty) values ('jezero-margin', 2, '{"es":"Episodio 2: el lago dejó sílice en las rocas que quedaron bajo la línea de agua.","en":"Episode 2: the lake left silica in rocks below the water line."}'::jsonb, 'interpretation');
insert into region_fact_sources (region_id, fact_ord, ord, source_id) values ('jezero-margin', 2, 0, 'src-34baed2a49a1');
insert into region_facts (region_id, ord, text, certainty) values ('jezero-margin', 3, '{"es":"Episodio 3: agua caliente dejó venas con sulfato de calcio y fluorita en la parte este.","en":"Episode 3: hot water left veins with calcium sulfate and fluorite in the eastern part."}'::jsonb, 'interpretation');
insert into region_fact_sources (region_id, fact_ord, ord, source_id) values ('jezero-margin', 3, 0, 'src-34baed2a49a1');
insert into pois (region_id, id, ord, geom, name, category, description, water_episode, elevation_m, confidence_note, is_example) values ('jezero-margin', 'base', 0, ST_SetSRID(ST_MakePoint(2950.0, 1100.0), 0), '{"es":"Base de la misión","en":"Mission base"}'::jsonb, 'base', '{"es":"Punto de salida y regreso de la caminata.","en":"Start and return point of the walk."}'::jsonb, null, -2399.8, '{"es":"Ubicación elegida por el equipo de TEPEXA en una zona plana del DTM (pendiente < 6° en 30 m). No es un sitio de NASA.","en":"Location chosen by the TEPEXA team on a flat area of the DTM (slope < 6° over 30 m). Not a NASA site."}'::jsonb, false);
